import React, { useReducer, useState } from "react";

import { Line } from "react-chartjs-2";
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from "chart.js"
ChartJS.register(
        CategoryScale,
        LinearScale,
        PointElement,
        LineElement,
        Title,
        Tooltip,
        Legend
    );

function LineChart({ csvData }) {
    let [labels, setLabels] = useState([]);
    let [ datas, setDatas ] = useState([]);

    useReducer(() => {
        console.log(csvData)
        if (!csvData.length > 0) {
            let property = Object.keys(data[0])
            setLabels(csvData.map((row) => row[property[0]]))
            setDatas(csvData.map((row) => parseFloat(row[property[1]])))
            console.log(labels)
            console.log(datas)
        }
    }, [labels, datas])


    const options = {
        responsive: true,
        plugins: {
            length: {
                position: 'top',
            },
            legend: {
                labels: {
                    usePointStyle: true,
                    pointStyleWidth: 20,
                },
                title: {
                    padding: 10,
                },
                onClick: function() {},
            },
            tooltip : {
                enabled: true,
                displayColors: false,
                callbacks : {
                    label: function (context) {
                        return `Value: ${context.parsed.y}`
                    }
                }
            },
            title: {
                display: true,
                text: 'Chart.js Line Chart',
                font: {
                    size: 18,
                },
                align: "start"
            },
            subtitle: {
                display: true,
                text: "Subtitle",
                font: {
                    size: 14,
                },
                align: "start",
            }
        },
        interaction: {
            mode: "nearest",
            axis: "x",
            intersect: false,
        },
        scales: {
            y: {
                display: true,
                title: {
                    display: true,
                    text: "The Number of Overdose",
                }
            },
            x: {
                display: true,
                title: {
                    display: true,
                    text: "Years"
                }
            }
        },
        elements: {
            line: {
                tension: .5
            },
            point: {
                radius: 3,
                hoverRadius: 10,
                hitRadius: 10,
            },
        }
    };

    const data = {
        labels,
        datasets: [
            {
                label: 'Dataset 1',
                data: datas,
                borderColor: 'rgb(255, 99, 132)',
                backgroundColor: 'rgba(255, 99, 132, 0.5)',
            },
        ],
    }

    return (
        <div className="chart-container">
            <Line options={options} data={data} />
        </div>
    )

}

export default LineChart;
